BEGIN;
INSERT INTO payments (id, idempotency_key, amount, status)
VALUES (gen_random_uuid(), $1, $2, 'created')
ON CONFLICT (idempotency_key) DO NOTHING;

INSERT INTO outbox (aggregate_id, type, payload)
SELECT id, 'payment.created', to_jsonb(p) FROM payments p WHERE idempotency_key = $1;
COMMIT;
