const EPOCH = 1700000000000n;
export class Snowflake {
  private last = -1n; private seq = 0n;
  constructor(private worker: bigint) { if (worker < 0n || worker > 1023n) throw new Error("worker 0..1023"); }
  next(): bigint {
    let now = BigInt(Date.now()) - EPOCH;
    if (now < this.last) now = this.last; // clock went backwards: never go back
    if (now === this.last) {
      this.seq = (this.seq + 1n) & 4095n;
      if (this.seq === 0n) { while (now <= this.last) now = BigInt(Date.now()) - EPOCH; }
    } else this.seq = 0n;
    this.last = now;
    return (now << 22n) | (this.worker << 12n) | this.seq;
  }
}

import { createHash } from "crypto";
const h = (s: string) => createHash("md5").update(s).digest().readUInt32BE(0);
export class Ring {
  private points: { p: number; node: string }[] = [];
  constructor(nodes: string[], private vnodes = 100) { nodes.forEach((n) => this.add(n)); }
  add(node: string) {
    for (let i = 0; i < this.vnodes; i++) this.points.push({ p: h(node + "#" + i), node });
    this.points.sort((a, b) => a.p - b.p);
  }
  remove(node: string) { this.points = this.points.filter((x) => x.node !== node); }
  get(key: string): string {
    const k = h(key); let lo = 0, hi = this.points.length - 1;
    if (k > this.points[hi].p) return this.points[0].node;
    while (lo < hi) { const m = (lo + hi) >> 1; if (this.points[m].p >= k) hi = m; else lo = m + 1; }
    return this.points[lo].node;
  }
}

type State = "closed" | "open" | "half";
export class Breaker {
  private state: State = "closed"; private fails = 0; private openedAt = 0;
  constructor(private threshold = 5, private cooldownMs = 10000) {}
  async call<T>(fn: () => Promise<T>): Promise<T> {
    if (this.state === "open") {
      if (Date.now() - this.openedAt < this.cooldownMs) throw new Error("circuit open");
      this.state = "half";
    }
    try {
      const r = await fn();
      this.state = "closed"; this.fails = 0; return r;
    } catch (e) {
      this.fails++;
      if (this.state === "half" || this.fails >= this.threshold) { this.state = "open"; this.openedAt = Date.now(); }
      throw e;
    }
  }
}

CREATE TABLE links (
  id          BIGINT PRIMARY KEY,          -- from the ID generator
  code        VARCHAR(10) NOT NULL UNIQUE, -- base62(id)
  long_url    TEXT NOT NULL,
  owner_id    BIGINT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at  TIMESTAMPTZ
);
CREATE INDEX links_owner_idx ON links (owner_id, created_at DESC);
